import { useNetworkData } from "../model";
import styles from "./Page.module.scss";

export function InterfacesPage() {
  const { interfaces, stats } = useNetworkData();

  return (
    <div className={styles["interfaces-page"]}>
      <div className={styles["box"]}>
        {interfaces.map((item) => {
            const stat = stats.find((s) => s.pcapName === item.pcapName);
            const isActive = item.flags?.includes("UP") && item.flags?.includes("RUNNING");

            return (
                <div className={styles["box__item"]}>
                    <h5>{item.localName || item.description || "Интерфейс"}</h5>
                </div>
            )
        })}
      </div>
    </div>
  );
}
